// Word timings for every spoken line (generated by scripts/generate-voice.mts).
import s1 from "../public/audio/vo/s1-hook.json";
import s2 from "../public/audio/vo/s2-film.json";
import s3 from "../public/audio/vo/s3-see.json";
import s4 from "../public/audio/vo/s4-price.json";
import s5 from "../public/audio/vo/s5-list.json";
import s6 from "../public/audio/vo/s6-negotiate.json";
import s6b from "../public/audio/vo/s6-scam.json";
import s7 from "../public/audio/vo/s7-teo.json";
import s7b from "../public/audio/vo/s7-kris.json";
import s7c from "../public/audio/vo/s7-bye.json";
import t1 from "../public/audio/vo/t1-teo.json";
import s8 from "../public/audio/vo/s8-sold.json";
import s9 from "../public/audio/vo/s9-punch.json";
import { VO_AT } from "./timing";

export type Word = { text: string; start: number; end: number };
export type VoClip = { id: string; text: string; duration: number; words: Word[] };

export const VO: Record<string, VoClip> = Object.fromEntries(
  [s1, s2, s3, s4, s5, s6, s6b, s7, s7b, s7c, s8, s9, t1].map((c) => [c.id, c as VoClip]),
);

// Absolute time (seconds) when word `index` of clip `id` starts (hook video clips only).
export const wordAt = (id: string, index: number) => VO_AT[id] + VO[id].words[index].start;

// Absolute time when the first word containing `needle` starts in clip `id`.
export const wordTime = (id: string, needle: string) => {
  const i = VO[id].words.findIndex((w) => w.text.toLowerCase().includes(needle.toLowerCase()));
  if (i < 0) throw new Error(`"${needle}" not found in ${id}`);
  return wordAt(id, i);
};
